def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row), key=lambda c: sum(row.count(c) for row in grid))
    # The small non-background marker color indicates the color to paint the
    # closest isolated object of the principal object color.
    counts = {}
    for row in grid:
        for c in row:
            if c != bg:
                counts[c] = counts.get(c, 0) + 1
    marker = min(counts, key=counts.get)
    out = [row[:] for row in grid]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r,c) in seen:
                continue
            color = grid[r][c]
            q = [(r,c)]
            seen.add((r,c))
            comp = []
            for y,x in q:
                comp.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and (ny,nx) not in seen and grid[ny][nx]==color:
                        seen.add((ny,nx)); q.append((ny,nx))
            comps.append((color,comp))
    # Marker pixels identify the unusual small marker; choose the nearest
    # component of the most numerous remaining color.
    target_color = max((c for c in counts if c != marker), key=lambda c: counts[c])
    marker_pts = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    candidates = [(comp) for color,comp in comps if color == target_color]
    if candidates:
        def dist(comp):
            return min(abs(r-y)+abs(c-x) for r,c in marker_pts for y,x in comp)
        chosen = min(candidates, key=dist)
        for r,c in chosen:
            out[r][c] = marker
    return out
